    public void nuggets(Object nugget, Object ingot) {
        shapeless(nugget, 9).requires(ingot).save();
        shaped(ingot).pattern("###", "###", "###").define('#', nugget).save(Refs.id(ingot).getPath() + "_from_nuggets");
    }

